class Solution {
public:
    bool repeatedSubstringPattern(string s) {
        int n = s.size();
        vector<int> fail(n, 0);
        for (int i = 1; i < n; i++) {
            int j = fail[i - 1];
            while (j > 0 && s[i] != s[j]) j = fail[j - 1];
            if (s[i] == s[j]) j++;
            fail[i] = j;
        }
        int p = n - fail[n - 1];
        return p < n && n % p == 0;
    }
};
